<?php
namespace App\Services;use App\Contracts\DnsResolver;use Illuminate\Validation\ValidationException;
class WebhookUrlGuard {public function __construct(private DnsResolver $resolver){}public function assertSafe(string $url):void{$parts=parse_url($url);if(!$parts||!isset($parts['scheme'],$parts['host']))$this->invalid();$scheme=strtolower($parts['scheme']);if(!in_array($scheme,['http','https'],true))$this->invalid();if($scheme==='http'&&!config('webhooks.allow_http'))throw ValidationException::withMessages(['url'=>['HTTPS is required.']]);if(isset($parts['user'])||isset($parts['pass']))throw ValidationException::withMessages(['url'=>['Credentials are not allowed in Webhook URLs.']]);$port=$parts['port']??($scheme==='https'?443:80);if(!in_array($port,config('webhooks.allowed_ports'),true))throw ValidationException::withMessages(['url'=>['Only standard HTTP and HTTPS ports are allowed.']]);$ips=$this->resolver->resolve(rtrim($parts['host'],'.'));if(!$ips)throw ValidationException::withMessages(['url'=>['Webhook hostname could not be resolved.']]);foreach($ips as $ip)if(!$this->publicIp($ip))throw ValidationException::withMessages(['url'=>['Webhook destination is not publicly routable.']]);}
 private function publicIp(string $ip):bool{if(str_starts_with(strtolower($ip),'::ffff:'))$ip=substr($ip,7);return filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)!==false;}private function invalid():never{throw ValidationException::withMessages(['url'=>['A valid HTTP or HTTPS Webhook URL is required.']]);}}
